class.description:
Les icônes de l'éditeur n'existent pas dans un jeu exporté : l'icône choisie est copiée dans [code]res://object_editor_icons/<nom>.res[/code] ([ImageTexture]) et c'est cette copie qui est utilisée. Éditeur uniquement, non instanciable.
[codeblock]
@tool
extends EditorScript

func _run() -> void:
	var icone := EditorIconPicker.copy_editor_icon("Node3D")
	print(icone.resource_path) # res://object_editor_icons/Node3D.res
[/codeblock]
